n('error',e=>{clearTimeout(t);reject(e);});child.on('close',code=>{clearTimeout(t);resolve({code,text,timedOut});});});}\n async function scenario(name,behavior,expected){await test(name,async()=>{\n  const seen=[],server=http.createServer((req,res)=>{seen.push(req.url);const mode=behavior[req.url];if(mode==='hang')return;if(mode===302)res.setHeader('Location','http://blocked.example.invalid/');res.writeHead(mode||200);res.end('fixture');});\n  const sockets=new Set();server.on('connection',s=>{sockets.add(s);s.on('close',()=>sockets.delete(s));});\n  await new Promise((resolve,reject)=>{server.once('error',reject);server.listen(0,'127.0.0.1',resolve);});\n  try{const result=await invoke('http://127.0.0.1:'+server.address().port);assert.equal(result.timedOut,false);assert.equal(result.code,expected);assert.deepEqual(seen,['/api/health','/ready']);}\n  finally{for(const socket of sockets)socket.destroy();await new Promise(r=>server.close(r));}\n });}\n await scenario('explicit_target_two_unique_successful_routes',{},0);\n await scenario('readiness_failure_is_not_healthy',{'/ready':503},1);\n await scenario('redirect_is_not_followed_or_accepted',{'/api/health':302},1);\n await scenario('unresponsive_route_is_bounded',{'/ready':'hang'},1);\n for(const[name,url]of [['external_target_rejected','http://example.invalid:5000'],['userinfo_rejected','http://user@localhost:5000'],['invalid_port_rejected','http://localhost:65536'],['shell_syntax_rejected','http://localhost:5000;echo injected']])await test(name,async()=>{const r=await invoke(url);assert.equal(r.code,2);assert.equal(r.timedOut,false);assert(!r.text.includes('ROUTE='));});\n const report={tests:results.length,pass:results.filter(x=>x.pass).length,results,scope:'REAL_CURL_WITH_SYNTHETIC_LOOPBACK_HTTP',productionApplicationRequests:0};fs.writeFileSync(cfg.result,JSON.stringify(report,null,2),{flag:'wx',mode:0o600});console.log(JSON.stringify(report));if(report.pass!==8||report.tests!==8)process.exitCode=2;\n})().cat